"""PyShield runtime. Generated by the PyShield builder; do not edit.

The module payloads in this build can only be decrypted with the build key
stored in a valid license file. Before any protected module is loaded the
signed package manifest is checked, so protected files and the runtime itself
cannot be modified without detection.
"""

from __future__ import annotations

import hashlib
import hmac
import json
import marshal
import os
import platform
import sys
import threading
import types
import zlib
from datetime import date, datetime, timedelta, timezone
from pathlib import Path

from . import _crypto
from . import _ed25519
from . import _machine

BUILD_ID = "__PYSHELD_BUILD_ID__"
MASTER_KEY_B85 = "__PYSHELD_MASTER_KEY__"
SIGNING_PUBLIC_KEY_B85 = "__PYSHELD_SIGNING_PUBLIC_KEY__"
PYTHON_VERSION = "__PYSHELD_PYTHON_VERSION__"
CIPHER = "__PYSHELD_CIPHER__"
INTEGRITY_MODE = "__PYSHELD_INTEGRITY__"
LICENSE_FORMAT = 2

LICENSE_SALT = b"pyshield-license-v1"
LICENSE_AAD_PREFIX = b"pyshield-license:"

MANIFEST_FILE = ".pyshield-manifest.json"
MANIFEST_FORMAT = 1
MANIFEST_CATEGORIES = ("code", "runtime", "data")

STATE_SALT = b"pyshield-state-v1"
STATE_DIR_ENV = "PYSHELD_STATE_DIR"
CLOCK_SKEW_DAYS = 1

BIND_ANY = "any"
BIND_FIRST_RUN = "first-run"
BIND_FIXED = "fixed"
BINDING_FILE = ".pyshield-binding.json"
BINDING_FILE_ENV = "PYSHELD_BINDING_FILE"
BINDING_FORMAT = 1
BINDING_SALT = b"pyshield-binding-v1"

_lock = threading.RLock()
_state: dict | None = None
_integrity: dict | None = None


class LicenseError(RuntimeError):
    """Raised when the build's license or package integrity is invalid."""


def _dist_dir() -> Path:
    return Path(__file__).resolve().parent.parent


def _runtime_dir() -> Path:
    return Path(__file__).resolve().parent


def _license_candidates() -> list[Path]:
    candidates: list[Path] = []
    env = os.environ.get("PYSHELD_LICENSE")
    if env:
        candidates.append(Path(env))
    candidates.append(_dist_dir() / "pyshield.lic")
    candidates.append(_runtime_dir() / "pyshield.lic")
    return candidates


def _read_license() -> tuple[Path, bytes]:
    for path in _license_candidates():
        if path.is_file():
            return path, path.read_bytes()
    locations = ", ".join(str(item) for item in _license_candidates()[:-1])
    raise LicenseError(
        "PyShield license not found; expected pyshield.lic next to manage.py"
        + (f", or PYSHELD_LICENSE ({locations})" if locations else "")
    )


def _license_key() -> bytes:
    master_key = _crypto.b85decode(MASTER_KEY_B85)
    return _crypto.hkdf_sha256(master_key, salt=LICENSE_SALT, info=BUILD_ID.encode("utf-8"), length=32)


def _check_runtime() -> None:
    if platform.python_implementation() != "CPython":
        raise LicenseError("PyShield builds require CPython")
    if "%d.%d" % sys.version_info[:2] != PYTHON_VERSION:
        raise LicenseError(
            f"this build targets CPython {PYTHON_VERSION}, "
            f"but the running interpreter is {platform.python_version()}"
        )


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _safe_relative(relative: str) -> bool:
    if not relative or "\\" in relative or relative.startswith("/") or ":" in relative:
        return False
    return ".." not in relative.split("/")


def _load_manifest() -> dict:
    path = _dist_dir() / MANIFEST_FILE
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except OSError as exc:
        raise LicenseError(
            f"PyShield package manifest {MANIFEST_FILE} is missing; deploy the complete build"
        ) from exc
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise LicenseError(f"PyShield package manifest {MANIFEST_FILE} is damaged") from exc
    if not isinstance(payload, dict) or payload.get("format") != MANIFEST_FORMAT:
        raise LicenseError("PyShield package manifest has an unsupported format")
    if payload.get("build_id") != BUILD_ID:
        raise LicenseError("PyShield package manifest belongs to a different build")
    if payload.get("cipher") != CIPHER:
        raise LicenseError("PyShield package manifest cipher does not match this build")
    if payload.get("integrity") != INTEGRITY_MODE:
        raise LicenseError("PyShield package manifest integrity mode does not match this build")
    signature = payload.get("signature")
    try:
        signed = (
            isinstance(signature, str)
            and _ed25519.verify(
                _crypto.b85decode(SIGNING_PUBLIC_KEY_B85),
                _crypto.manifest_signing_message(payload),
                _crypto.b85decode(signature),
            )
        )
    except Exception:
        signed = False
    if not signed:
        raise LicenseError("PyShield package manifest signature is invalid")
    files = payload.get("files")
    if not isinstance(files, dict) or not files:
        raise LicenseError("PyShield package manifest contains no file list")
    return payload


def _scan_integrity(full: bool) -> dict:
    """Hash protected package files; returns {enabled, checked, failures}."""
    if INTEGRITY_MODE == "off":
        return {"enabled": False, "checked": 0, "failures": []}

    payload = _load_manifest()
    categories = {"code", "runtime"}
    if full or INTEGRITY_MODE == "full":
        categories.add("data")

    root = _dist_dir()
    failures: list[str] = []
    checked = 0
    for relative, info in payload["files"].items():
        if not _safe_relative(relative) or not isinstance(info, dict):
            failures.append(f"invalid manifest entry: {relative!r}")
            continue
        category = info.get("category")
        if category not in MANIFEST_CATEGORIES:
            failures.append(f"unknown category for {relative}")
            continue
        if category not in categories:
            continue
        target = root / relative
        try:
            if target.is_symlink() or not target.is_file():
                raise OSError("file is missing")
            if target.stat().st_size != info.get("size"):
                raise OSError("size mismatch")
            if _sha256_file(target) != info.get("sha256"):
                raise OSError("hash mismatch")
        except OSError as exc:
            failures.append(f"{relative}: {exc}")
        checked += 1
    return {"enabled": True, "checked": checked, "failures": failures}


def _enforce_integrity() -> None:
    global _integrity
    if _integrity is None:
        with _lock:
            if _integrity is None:
                _integrity = _scan_integrity(full=INTEGRITY_MODE == "full")
    failures = _integrity["failures"]
    if failures:
        details = "; ".join(failures[:5])
        if len(failures) > 5:
            details += f"; and {len(failures) - 5} more"
        raise LicenseError(
            "PyShield package integrity check failed (" + details + "); "
            "restore the original files or contact the vendor"
        )


def verify_package(full: bool = False) -> dict:
    """Verify the signed package manifest without loading a license.

    By default protected code and the runtime are hashed; ``full=True`` also
    hashes templates, static files and other packaged data.
    """
    try:
        report = _scan_integrity(full=full)
    except LicenseError as exc:
        return {"ok": False, "enabled": INTEGRITY_MODE != "off", "checked": 0, "failures": [str(exc)]}
    return {
        "ok": not report["failures"],
        "enabled": report["enabled"],
        "checked": report["checked"],
        "failures": report["failures"],
    }


def _clock_path() -> Path:
    directory = os.environ.get(STATE_DIR_ENV)
    if directory:
        return Path(directory) / (BUILD_ID + ".state")
    try:
        home = Path.home()
    except (RuntimeError, OSError):
        return _runtime_dir() / ".pyshield-state.json"
    return home / ".pyshield" / (BUILD_ID + ".state")


def _clock_key(build_key: bytes) -> bytes:
    return _crypto.hkdf_sha256(
        build_key, salt=STATE_SALT, info=BUILD_ID.encode("utf-8"), length=32
    )


def _clock_mac(key: bytes, last_seen: str) -> str:
    message = (BUILD_ID + "|" + last_seen).encode("utf-8")
    return hmac.new(key, message, hashlib.sha256).hexdigest()


def _read_clock(build_key: bytes) -> tuple[date | None, Path]:
    path = _clock_path()
    try:
        raw = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        return None, path
    except OSError:
        return None, path
    try:
        record = json.loads(raw)
        last_seen = str(record["last_seen"])
        mac = str(record["mac"])
        build_id = record.get("build_id")
        seen_date = date.fromisoformat(last_seen)
    except (ValueError, KeyError, TypeError, json.JSONDecodeError) as exc:
        raise LicenseError(
            f"PyShield clock state {path} is damaged; restore the file or correct the system clock"
        ) from exc
    if build_id != BUILD_ID:
        return None, path
    if not hmac.compare_digest(_clock_mac(_clock_key(build_key), last_seen), mac):
        raise LicenseError(
            f"PyShield clock state {path} was modified; restore the file or reinstall the build"
        )
    return seen_date, path


def _write_clock(build_key: bytes, path: Path, seen: date) -> None:
    last_seen = seen.isoformat()
    record = {
        "build_id": BUILD_ID,
        "last_seen": last_seen,
        "mac": _clock_mac(_clock_key(build_key), last_seen),
    }
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(path.name + ".tmp")
        temporary.write_text(
            json.dumps(record, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
        os.replace(temporary, path)
    except OSError:
        # Read-only deployments keep working; rollback detection is best effort.
        pass


def _binding_path() -> Path:
    override = os.environ.get(BINDING_FILE_ENV)
    if override:
        return Path(override)
    return _dist_dir() / BINDING_FILE


def _binding_key(build_key: bytes) -> bytes:
    return _crypto.hkdf_sha256(
        build_key, salt=BINDING_SALT, info=BUILD_ID.encode("utf-8"), length=32
    )


def _binding_mac(key: bytes, fingerprint: str, bound_at: str) -> str:
    message = "|".join((BUILD_ID, fingerprint, bound_at)).encode("utf-8")
    return hmac.new(key, message, hashlib.sha256).hexdigest()


def _write_binding(key: bytes, path: Path, fingerprint: str) -> str:
    bound_at = datetime.now(timezone.utc).isoformat(timespec="seconds")
    record = {
        "format": BINDING_FORMAT,
        "build_id": BUILD_ID,
        "fingerprint": fingerprint,
        "bound_at": bound_at,
        "mac": _binding_mac(key, fingerprint, bound_at),
    }
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(path.name + ".tmp")
        temporary.write_text(
            json.dumps(record, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
        os.replace(temporary, path)
    except OSError as exc:
        raise LicenseError(
            f"PyShield cannot record the first-run binding in {path} ({exc}); "
            "run once with write permission or ask the vendor for a fixed license"
        ) from exc
    return bound_at


def _check_first_run_binding(build_key: bytes) -> str:
    path = _binding_path()
    current = _machine.machine_fingerprint().lower()
    try:
        raw = path.read_text(encoding="utf-8")
    except FileNotFoundError:
        _write_binding(_binding_key(build_key), path, current)
        return current
    except OSError as exc:
        raise LicenseError(f"PyShield binding file {path} cannot be read: {exc}") from exc
    try:
        record = json.loads(raw)
        fingerprint = str(record["fingerprint"]).lower()
        bound_at = str(record["bound_at"])
        mac = str(record["mac"])
    except (ValueError, KeyError, TypeError, json.JSONDecodeError) as exc:
        raise LicenseError(
            f"PyShield binding file {path} is damaged; restore it from backup "
            "or contact the vendor"
        ) from exc
    if record.get("format") != BINDING_FORMAT or record.get("build_id") != BUILD_ID:
        raise LicenseError(f"PyShield binding file {path} belongs to a different build")
    expected = _binding_mac(_binding_key(build_key), fingerprint, bound_at)
    if not hmac.compare_digest(expected, mac):
        raise LicenseError(
            f"PyShield binding file {path} was modified; restore it from backup "
            "or contact the vendor"
        )
    if fingerprint != current:
        raise LicenseError(
            f"this deployment is bound to machine {fingerprint} "
            f"(current machine {current}); contact the vendor to rebind it"
        )
    return fingerprint


def _check_binding(build_key: bytes, payload: dict) -> tuple[str, list[str], str | None]:
    mode = str(payload.get("bind_mode") or "").strip().lower()
    fingerprints = [str(item).lower() for item in payload.get("fingerprints") or []]
    if mode not in (BIND_ANY, BIND_FIRST_RUN, BIND_FIXED):
        mode = BIND_FIXED if fingerprints else BIND_ANY
    if mode == BIND_ANY:
        return mode, [], None
    if mode == BIND_FIRST_RUN:
        return mode, [], _check_first_run_binding(build_key)
    if not fingerprints:
        raise LicenseError("license uses fixed binding but lists no fingerprints")
    current = _machine.machine_fingerprint().lower()
    if current not in fingerprints:
        raise LicenseError(
            f"this machine is not licensed (fingerprint {current}); "
            "contact the vendor to reissue the license"
        )
    return mode, fingerprints, current


def _check_clock(build_key: bytes) -> str:
    today = date.today()
    seen, path = _read_clock(build_key)
    if seen is not None:
        if today < seen - timedelta(days=CLOCK_SKEW_DAYS):
            raise LicenseError(
                "PyShield detected a system clock rollback "
                f"(last seen {seen.isoformat()}, today {today.isoformat()}); "
                "synchronize the system clock and retry"
            )
        if today <= seen:
            return seen.isoformat()
    _write_clock(build_key, path, today)
    return today.isoformat()


def _load_state() -> dict:
    global _state
    if _state is not None:
        return _state
    with _lock:
        if _state is not None:
            return _state

        _check_runtime()
        _enforce_integrity()

        path, sealed = _read_license()
        try:
            data = _crypto.open_envelope(_license_key(), sealed, LICENSE_AAD_PREFIX + BUILD_ID.encode("utf-8"))
            payload = json.loads(data.decode("utf-8"))
        except _crypto.CryptoError as exc:
            raise LicenseError(f"license {path} is invalid or corrupted") from exc
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise LicenseError(f"license {path} is damaged") from exc

        if payload.get("format") != LICENSE_FORMAT:
            raise LicenseError(f"license {path} has an unsupported format")

        signature = payload.get("signature")
        try:
            signed = (
                isinstance(signature, str)
                and _ed25519.verify(
                    _crypto.b85decode(SIGNING_PUBLIC_KEY_B85),
                    _crypto.license_signing_message(payload),
                    _crypto.b85decode(signature),
                )
            )
        except Exception:
            signed = False
        if not signed:
            raise LicenseError(f"license {path} has an invalid signature")

        if payload.get("build_id") != BUILD_ID:
            raise LicenseError(f"license {path} does not belong to this build")

        try:
            build_key = _crypto.b85decode(payload["build_key"])
        except Exception as exc:
            raise LicenseError("license is missing the build key") from exc
        if len(build_key) != 32:
            raise LicenseError("license contains an invalid build key")

        bind_mode, fingerprints, bound_fingerprint = _check_binding(build_key, payload)
        last_seen = _check_clock(build_key)

        today = date.today()
        not_before = payload.get("not_before")
        if not_before:
            try:
                issued = date.fromisoformat(str(not_before))
            except ValueError as exc:
                raise LicenseError("license contains an invalid issue date") from exc
            if today < issued - timedelta(days=CLOCK_SKEW_DAYS):
                raise LicenseError(
                    f"license is not valid before {not_before}; synchronize the system clock"
                )

        try:
            grace_days = int(payload.get("grace_days") or 0)
        except (TypeError, ValueError) as exc:
            raise LicenseError("license contains invalid grace days") from exc
        if grace_days < 0:
            raise LicenseError("license contains invalid grace days")

        expires = payload.get("expires")
        in_grace = False
        if expires:
            try:
                expires_date = date.fromisoformat(str(expires))
            except ValueError as exc:
                raise LicenseError("license contains an invalid expiry date") from exc
            if today > expires_date + timedelta(days=grace_days):
                if grace_days:
                    raise LicenseError(
                        f"license expired on {expires} and the {grace_days}-day grace period has ended"
                    )
                raise LicenseError(f"license expired on {expires}")
            in_grace = today > expires_date

        _state = {
            "build_key": build_key,
            "license": path,
            "not_before": not_before,
            "expires": expires,
            "grace_days": grace_days,
            "in_grace": in_grace,
            "last_seen": last_seen,
            "bind_mode": bind_mode,
            "fingerprints": fingerprints,
            "bound_fingerprint": bound_fingerprint,
            "customer": payload.get("customer"),
        }
        return _state


def _replace_filename(code: types.CodeType, filename: str) -> types.CodeType:
    consts = tuple(
        _replace_filename(item, filename) if isinstance(item, types.CodeType) else item
        for item in code.co_consts
    )
    # Code objects compare equal even when co_filename differs, so always rebuild.
    return code.replace(co_filename=filename, co_consts=consts)


def load_module(name: str, file: str, payload: str, module_id: str) -> None:
    """Decrypt and execute one protected module inside its real module namespace."""
    state = _load_state()
    key = _crypto.derive_module_key(state["build_key"], module_id)
    try:
        raw = _crypto.open_envelope(
            key, _crypto.b85decode(payload), _crypto.module_aad(BUILD_ID, module_id)
        )
        code = marshal.loads(zlib.decompress(raw))
    except _crypto.CryptoError as exc:
        raise ImportError(f"PyShield: cannot decrypt protected module {module_id}") from exc
    except Exception as exc:
        raise ImportError(f"PyShield: protected module {module_id} is corrupted") from exc

    if not isinstance(code, types.CodeType):
        raise ImportError(f"PyShield: protected module {module_id} has an invalid payload")

    code = _replace_filename(code, file)
    module = sys.modules.get(name)
    namespace = module.__dict__ if module is not None else {"__name__": name, "__file__": file}
    exec(code, namespace)


def reload_license() -> dict:
    """Re-read the license file so a renewed license takes effect without a restart."""
    global _state
    with _lock:
        _state = None
    return license_status()


def license_status(refresh: bool = False) -> dict:
    """Return license and clock details; raises LicenseError when unusable."""
    if refresh:
        return reload_license()
    state = _load_state()
    return {
        "build_id": BUILD_ID,
        "license": str(state["license"]),
        "not_before": state["not_before"],
        "expires": state["expires"],
        "grace_days": state["grace_days"],
        "in_grace": state["in_grace"],
        "last_seen": state["last_seen"],
        "bind_mode": state["bind_mode"],
        "fingerprints": state["fingerprints"],
        "bound_fingerprint": state["bound_fingerprint"],
        "customer": state["customer"],
        "cipher": CIPHER,
        "integrity": INTEGRITY_MODE,
        "signature": "ed25519",
    }
